mapper.select:
SELECT FROM PHOTO_POSTS PP JOIN USERS U ON U.USER_ID = PP.CREATED_BY LEFT JOIN PHOTO_ALBUMS A ON A.ALBUM_ID = PP.ALBUM_ID WHERE ( (PP.SCOPE_TYPE = #{scopeType} AND PP.SCOPE_ID = #{scopeId}) OR (#{scopeType} = 'PERSONAL' AND #{albumId,jdbcType=NUMERIC} IS NULL AND PP.SCOPE_TYPE = 'PERSONAL' AND NVL(PP.VISIBILITY_TYPE, 'PRIVATE') = 'FRIENDS' AND PP.CREATED_BY <> #{userId} AND EXISTS ( SELECT 1 FROM USER_FRIENDS UF WHERE UF.STATUS = 'ACCEPTED' AND ( (UF.REQUESTER_ID = #{userId} AND UF.ADDRESSEE_ID = PP.CREATED_BY) OR (UF.ADDRESSEE_ID = #{userId} AND UF.REQUESTER_ID = PP.CREATED_BY) ) ) ) OR EXISTS ( SELECT 1 FROM CONTENT_SHARES CS WHERE CS.CONTENT_TYPE = 'PHOTO' AND CS.CONTENT_ID = PP.POST_ID AND CS.ACTIVE_YN = 'Y' AND NVL(CS.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND (CS.EXPIRES_AT IS NULL OR CS.EXPIRES_AT >= SYSDATE) AND ( (#{scopeType} = 'PERSONAL' AND CS.TARGET_TYPE = 'USER' AND CS.TARGET_ID = #{userId}) OR (#{scopeType} = 'WORKSPACE' AND CS.TARGET_TYPE = 'WS' AND CS.TARGET_ID = #{scopeId} AND EXISTS (SELECT 1 FROM WS_MEMBERS WSM WHERE WSM.WS_ID = CS.TARGET_ID AND WSM.USER_ID = #{userId})) OR (#{scopeType} = 'PROJECT' AND CS.TARGET_TYPE = 'PROJ' AND CS.TARGET_ID = #{scopeId} AND EXISTS (SELECT 1 FROM PROJ_MEMBERS PM WHERE PM.PROJ_ID = CS.TARGET_ID AND PM.USER_ID = #{userId})) ) ) ) AND NVL(PP.DELETED_YN, 'N') = 'N'
AND PP.ALBUM_ID = #{albumId}
ORDER BY PP.CREATED_AT DESC, PP.POST_ID DESC

mapper.update:
UPDATE PHOTOS
   SET ALBUM_ID = #{albumId,jdbcType=NUMERIC}
 WHERE POST_ID = #{postId}

mapper.select:
SELECT COUNT(*)
  FROM PHOTO_POSTS
 WHERE POST_ID = #{postId}
   AND NVL(DELETED_YN, 'N') = 'Y'
   AND DELETED_BY = #{userId}

SELECT COUNT(1)
  FROM CONTENT_REACTIONS
 WHERE CONTENT_TYPE = 'PHOTO_POST'
   AND CONTENT_ID = #{postId}
   AND USER_ID = #{userId}
   AND REACTION_TYPE = 'COLLECT'

mapper.insert:
INSERT INTO CONTENT_REACTIONS (
    REACTION_ID, CONTENT_TYPE, CONTENT_ID, USER_ID, REACTION_TYPE, CREATED_AT
)
SELECT SEQ_CONTENT_REACTION_ID.NEXTVAL, 'PHOTO_POST', #{postId}, #{userId}, 'COLLECT', SYSDATE
  FROM DUAL
 WHERE NOT EXISTS (
    SELECT 1
      FROM CONTENT_REACTIONS
     WHERE CONTENT_TYPE = 'PHOTO_POST'
       AND CONTENT_ID = #{postId}
       AND USER_ID = #{userId}
       AND REACTION_TYPE = 'COLLECT'
 )

INSERT INTO CONTENT_REACTIONS (
    REACTION_ID, CONTENT_TYPE, CONTENT_ID, USER_ID, REACTION_TYPE, CREATED_AT
)
SELECT SEQ_CONTENT_REACTION_ID.NEXTVAL, 'PHOTO_COLLECT_LINK', #{collectedPostId}, #{userId}, 'SRC_' || #{sourcePostId}, SYSDATE
  FROM DUAL
 WHERE NOT EXISTS (
    SELECT 1
      FROM CONTENT_REACTIONS
     WHERE CONTENT_TYPE = 'PHOTO_COLLECT_LINK'
       AND CONTENT_ID = #{collectedPostId}
       AND USER_ID = #{userId}
 )

mapper.select:
SELECT CONTENT_ID
  FROM CONTENT_REACTIONS
 WHERE CONTENT_TYPE = 'PHOTO_COLLECT_LINK'
   AND USER_ID = #{userId}
   AND REACTION_TYPE = 'SRC_' || #{sourcePostId}
   AND ROWNUM = 1

mapper.delete:
DELETE FROM CONTENT_REACTIONS
 WHERE CONTENT_TYPE = 'PHOTO_POST'
   AND CONTENT_ID = #{postId}
   AND USER_ID = #{userId}
   AND REACTION_TYPE = 'COLLECT'

DELETE FROM CONTENT_REACTIONS
 WHERE CONTENT_TYPE = 'PHOTO_COLLECT_LINK'
   AND CONTENT_ID = #{collectedPostId}

mapper.select:
SELECT COUNT(1)
  FROM PHOTO_POST_COMMENTS
 WHERE POST_ID = #{postId}
   AND COMMENT_ID = #{commentId}
   AND NVL(DELETED_YN, 'N') = 'N'

mapper.update:
UPDATE PHOTO_POST_COMMENTS
   SET COMMENT_CONTENT = #{content},
       UPDATED_AT = SYSDATE
 WHERE COMMENT_ID = #{commentId}
   AND POST_ID = #{postId}
   AND USER_ID = #{userId}
   AND NVL(DELETED_YN, 'N') = 'N'

UPDATE PHOTO_POST_COMMENTS
   SET DELETED_YN = 'Y',
       COMMENT_CONTENT = '삭제된 댓글입니다.',
       UPDATED_AT = SYSDATE
 WHERE COMMENT_ID = #{commentId}
   AND POST_ID = #{postId}
   AND NVL(DELETED_YN, 'N') = 'N'
   AND (
        USER_ID = #{userId}
        OR #{canManage} = 1
   )
